import { Schema as S } from "effect"

/** Connection settings used when delivering an event to a subscriber. */
export const WebhookDestination = S.Struct({
  /** Subscriber-configured endpoint; redirects are not followed during delivery. */
  url: S.String.annotateKey({
    description: "Subscriber-configured endpoint; redirects are not followed during delivery."
  }),
  /** Total delivery budget in milliseconds, including DNS resolution and TLS setup. */
  timeoutMs: S.Number.annotateKey({
    description: "Total delivery budget in milliseconds, including DNS resolution and TLS setup."
  })
}).annotate({
  description: "Connection settings used when delivering an event to a subscriber."
})

/** Delivery was refused before connecting because DNS resolved to a forbidden network. */
export class WebhookNetworkDenied extends S.TaggedError<WebhookNetworkDenied>()(
  "WebhookNetworkDenied",
  {
    /** Identifier of the queued delivery that was refused; not a subscriber identifier. */
    deliveryId: S.String.annotateKey({
      description: "Identifier of the queued delivery that was refused; not a subscriber identifier."
    }),
    /** Hostname from the configured endpoint, before DNS resolution. */
    hostname: S.String.annotateKey({
      description: "Hostname from the configured endpoint, before DNS resolution."
    }),
    /** DNS-resolved IP rejected by the SSRF policy; may reveal internal network details and must not appear in subscriber-facing errors. */
    resolvedAddress: S.String.annotateKey({
      description: "DNS-resolved IP rejected by the SSRF policy; may reveal internal network details and must not appear in subscriber-facing errors."
    })
  }
) {}
